const SCHOOL_PERMISSIONS=['structure','students','subjects','teachers','assign','grades','office','routing','sms','announce','promotion'];
function school_id(): string{return bin2hex(random_bytes(16));}
function school_find(array $rows,string $id): ?array{foreach($rows as $r)if(($r['id']??null)===$id)return $r;return null;}
function school_actor(array $u): string{return $u['role']==='admin'?'admin':(string)($u['actor_id']??'');}
function school_can(array $life,string $actor,string $permission): bool{if($actor==='admin'||$actor==='deputy')return true;$person=school_find($life['people'],$actor);if(($person['roleId']??'')==='deputy')return true;$role=school_find($life['roles'],(string)($person['roleId']??''));return in_array($permission,$role['permissions']??[],true);}
function school_require(bool $condition,string $message='این تغییر در دسترسی شما نیست.'): void{if(!$condition)throw new InvalidArgumentException($message);}
function school_empty(): array{return ['d'=>['years'=>[['id'=>school_id(),'name'=>'۱۴۰۵–۱۴۰۶','archived'=>false]],'majors'=>[],'grades'=>[['id'=>'g10','name'=>'دهم','order'=>10],['id'=>'g11','name'=>'یازدهم','order'=>11],['id'=>'g12','name'=>'دوازدهم','order'=>12]],'classes'=>[],'students'=>[],'enrollments'=>[],'teachers'=>[],'subjects'=>[],'offerings'=>[],'sessions'=>[],'finals'=>[],'incidents'=>[],'attendanceFollowup'=>[],'customFields'=>[]],'life'=>['roles'=>[],'people'=>[],'notices'=>[],'messages'=>[],'routes'=>['default'=>'admin'],'dispatches'=>[],'tasks'=>[],'submissions'=>[],'announcements'=>[],'contacts'=>[],'sms'=>[],'smsConfig'=>['provider'=>'سرویس انتخاب نشده','sender'=>''],'notificationPrefs'=>[]]];}
