function school_same(mixed $a,mixed $b): bool{return $a==$b;}
function school_notify(array &$l,string $to,string $title,string $body,string $page): void{$l['notices'][]=['id'=>school_id(),'to'=>$to,'title'=>$title,'body'=>$body,'page'=>$page,'date'=>date('Y-m-d'),'read'=>false];}
function school_visible(array $state,string $actor): array{
 $d=$state['d'];$l=$state['life'];$teacher=str_starts_with($actor,'teacher:')?substr($actor,8):null;$student=str_starts_with($actor,'student:')?substr($actor,8):null;$admin=$actor==='admin';
 $roster=$admin||school_can($l,$actor,'students')||school_can($l,$actor,'office')||school_can($l,$actor,'grades');
 $classIds=[];if($teacher)foreach($d['offerings'] as $o)if($o['teacherId']===$teacher)$classIds[]=$o['classId'];if($student)foreach($d['enrollments'] as $e)if($e['studentId']===$student&&$e['status']==='active')$classIds[]=$e['classId'];
 $courseIds=[];foreach($d['offerings'] as $o)if(($teacher&&$o['teacherId']===$teacher)||($student&&in_array($o['classId'],$classIds,true))||(!$teacher&&!$student&&($roster||school_can($l,$actor,'assign')||school_can($l,$actor,'subjects')||school_can($l,$actor,'structure'))))$courseIds[]=$o['id'];
 $allClasses=!$teacher&&!$student&&($roster||school_can($l,$actor,'structure')||school_can($l,$actor,'assign')||school_can($l,$actor,'subjects'));
 $d['classes']=array_values(array_filter($d['classes'],fn($c)=>$allClasses||in_array($c['id'],$classIds,true)));
 $d['offerings']=array_values(array_filter($d['offerings'],fn($o)=>in_array($o['id'],$courseIds,true)));
 $d['enrollments']=array_values(array_filter($d['enrollments'],fn($e)=>$student?$e['studentId']===$student:($roster||in_array($e['classId'],$classIds,true))));
 $studentIds=array_column($d['enrollments'],'studentId');$d['students']=array_values(array_filter($d['students'],fn($s)=>$roster||in_array($s['id'],$studentIds,true)));
 if($teacher||$student)foreach($d['students'] as &$s){unset($s['phone'],$s['extra']);}unset($s);
 $gradeRead=$teacher||$student||school_can($l,$actor,'grades');$office=school_can($l,$actor,'office');
 $d['sessions']=array_values(array_filter($d['sessions'],fn($s)=>in_array($s['courseId'],$courseIds,true)&&($gradeRead||$office)));
 foreach($d['sessions'] as &$s){foreach($s['records'] as $id=>&$r){if($student&&$id!==$student)unset($s['records'][$id]);elseif(!$gradeRead){$r['marks']=[];$r['note']='';$r['asked']=false;}}unset($r);}unset($s);
 $d['finals']=array_filter($d['finals'],function($f,$key)use($gradeRead,$courseIds,$student){$p=explode(':',$key);return $gradeRead&&count($p)===3&&in_array($p[0],$courseIds,true)&&(!$student||$p[2]===$student);},ARRAY_FILTER_USE_BOTH);
 $d['incidents']=$office?$d['incidents']:[];$d['attendanceFollowup']=$office?$d['attendanceFollowup']:[];
