 $l['tasks']=array_values(array_filter($l['tasks'],fn($t)=>in_array($t['courseId'],$courseIds,true)&&($teacher||($student&&$t['published']))));
 if($student)foreach($l['tasks'] as &$t)foreach($t['questions'] as &$q)unset($q['correct']);unset($t,$q);
 $taskIds=array_column($l['tasks'],'id');$l['submissions']=array_values(array_filter($l['submissions'],fn($s)=>in_array($s['taskId'],$taskIds,true)&&($teacher||$s['studentId']===$student)));
