 $l['contacts']=school_can($l,$actor,'sms')||$office?$l['contacts']:[];$l['sms']=school_can($l,$actor,'sms')?$l['sms']:[];
 $l['announcements']=array_values(array_filter($l['announcements'],fn($a)=>$a['audience']==='all'||($student?$a['audience']==='students':$a['audience']==='staff')));
 $l['notificationPrefs']=isset($l['notificationPrefs'][$actor])?[$actor=>$l['notificationPrefs'][$actor]]:[];
 return ['d'=>$d,'life'=>$l];
