function school_merge_rows(array $original,array $visible,array $incoming,callable $check): array{
 school_require(array_is_list($incoming)&&count($incoming)<=20000,'فهرست نامعتبر یا بیش از ظرفیت است.');$seen=[];
 foreach($incoming as $row){school_require(is_array($row)&&is_string($row['id']??null)&&preg_match('/^[\p{L}\p{N}_:-]{1,100}$/u',$row['id'])===1,'شناسه معتبر نیست.');$id=$row['id'];school_require(!isset($seen[$id]),'شناسه تکراری است.');$seen[$id]=true;$old=school_find($original,$id);$shown=school_find($visible,$id);school_require(!$old||$shown!==null);if($shown!==null&&school_same($row,$shown))continue;$new=$check($old,$row);if($old){foreach($original as $i=>$r)if($r['id']===$id){$original[$i]=$new;break;}}else $original[]=$new;}
 foreach($visible as $r)school_require(isset($seen[$r['id']]),'حذف مستقیم سوابق مجاز نیست.');return $original;
}
function school_only(array $old,array $new,array $fields): void{foreach(array_unique(array_merge(array_keys($old),array_keys($new))) as $key)if(!in_array($key,$fields,true))school_require(school_same($old[$key]??null,$new[$key]??null),'تغییر فیلد محافظت‌شده مجاز نیست: '.$key);}
function school_validate(array $state): void{
 $d=$state['d'];$l=$state['life'];$seen=[];foreach(['years','majors','grades','classes','students','teachers','subjects','offerings','enrollments','sessions','incidents','customFields'] as $key){school_require(isset($d[$key])&&is_array($d[$key])&&array_is_list($d[$key]),'ساختار داده معتبر نیست: '.$key);$ids=array_column($d[$key],'id');school_require(count(array_unique($ids))===count($ids),'شناسه تکراری است.');}
