 foreach($d['students'] as $s){foreach($s['extra']??[] as $key=>$value){$field=school_find($d['customFields'],(string)$key);school_require($field&&is_string($value)&&strlen($value)<=6000,'مشخصه دانش‌آموز معتبر نیست.');if($value!==''){if($field['type']==='number')school_require(is_numeric($value),'مشخصه عددی معتبر نیست.');if($field['type']==='date')school_require(school_date($value),'تاریخ مشخصه معتبر نیست.');}}school_require(!empty($s['name'])&&!empty($s['father'])&&!empty($s['code']),'نام، نام پدر و کد دانش‌آموز لازم است.');school_require(!isset($seen['code:'.$s['code']]),'کد دانش‌آموز تکراری است.');$seen['code:'.$s['code']]=1;school_require(empty($s['phone'])||preg_match('/^09[0-9]{9}$/D',$s['phone'])===1,'شماره دانش‌آموز معتبر نیست.');}
 foreach($d['customFields'] as $field)school_require(!empty($field['name'])&&in_array($field['type'],['text','number','date'],true)&&is_bool($field['required']),'مشخصه دلخواه معتبر نیست.');
 foreach($d['teachers'] as $t)school_require(!empty($t['name'])&&filter_var($t['email'],FILTER_VALIDATE_EMAIL)&&preg_match('/^09[0-9]{9}$/D',$t['phone']??'')===1,'نام، ایمیل و شماره همراه معتبر معلم الزامی است.');
 foreach($d['enrollments'] as $e){school_require(school_find($d['students'],$e['studentId'])&&school_find($d['years'],$e['yearId']),'پرونده ثبت‌نام نامعتبر است.');$key=$e['yearId'].':'.$e['studentId'];school_require(!isset($seen[$key]),'هر دانش‌آموز فقط یک ثبت‌نام در هر سال دارد.');$seen[$key]=1;if($e['status']==='active'){ $c=school_find($d['classes'],(string)$e['classId']);school_require($c&&$c['yearId']===$e['yearId'],'سال و کلاس ثبت‌نام سازگار نیستند.');}else school_require($e['status']==='graduated'&&$e['classId']===null);}
 foreach($d['offerings'] as $o){$c=school_find($d['classes'],$o['classId']);$s=school_find($d['subjects'],$o['subjectId']);school_require($c&&$s&&$s['gradeId']===$c['gradeId']&&($s['majorId']==='all'||$s['majorId']===$c['majorId']),'درس با پایه و رشته کلاس سازگار نیست.');school_require(empty($o['teacherId'])||school_find($d['teachers'],$o['teacherId']),'معلم درس معتبر نیست.');school_require(count($o['modules'])===5,'هر درس باید پنج پودمان داشته باشد.');foreach($o['modules'] as $m)school_require(in_array($m['competencies'],[1,2],true));school_formula($o['formula']??[]);}
