function school_date(mixed $value): bool{if(!is_string($value)||!preg_match('/^(\d{4})-(\d{2})-(\d{2})$/D',$value,$m))return false;return checkdate((int)$m[2],(int)$m[3],(int)$m[1]);}
function school_formula(array $formula): void{$expression=$formula['expression']??'';school_require(is_string($expression)&&strlen($expression)<=512&&preg_match('/^[0-9a-zA-Z_+*\/%(),.<>!=\s-]+$/D',$expression)===1,'فرمول نمره معتبر نیست.');preg_match_all('/[a-zA-Z_]+/',$expression,$m);$allowed=['avg','count','positive','negative','attendance','classwork','workshop','written','oral','discipline','presentation','homework','min','max','if','round'];school_require(!array_diff($m[0],$allowed),'متغیر فرمول شناخته‌شده نیست.');foreach(['minimum','high','pass'] as $key)school_require(is_numeric($formula[$key]??null)&&$formula[$key]>=0&&$formula[$key]<=20,'حد فرمول معتبر نیست.');school_require($formula['minimum']<=$formula['high']&&in_array((float)($formula['round']??0),[0.5,1.0],true),'گردکردن فرمول معتبر نیست.');}
function school_course_active(array $d,string $id): bool{$o=school_find($d['offerings'],$id);$c=$o?school_find($d['classes'],$o['classId']):null;$y=$c?school_find($d['years'],$c['yearId']):null;return $y&&!$y['archived'];}
