function school_student_course(array $d,string $studentId,string $courseId): bool{$o=school_find($d['offerings'],$courseId);$c=$o?school_find($d['classes'],$o['classId']):null;if(!$c)return false;foreach($d['enrollments'] as $e)if($e['studentId']===$studentId&&$e['classId']===$c['id']&&$e['yearId']===$c['yearId']&&$e['status']==='active')return true;return false;}
function school_message_allowed(array $d,array $l,string $from,string $to): bool{
 if($from===$to)return false;$student=str_starts_with($from,'student:')?$from:(str_starts_with($to,'student:')?$to:null);$teacher=str_starts_with($from,'teacher:')?$from:(str_starts_with($to,'teacher:')?$to:null);
 $exists=fn($id)=>in_array($id,['admin','deputy'],true)||school_find($l['people'],$id)||str_starts_with($id,'teacher:')&&school_find($d['teachers'],substr($id,8))||str_starts_with($id,'student:')&&school_find($d['students'],substr($id,8));if(!$exists($from)||!$exists($to))return false;if(!$student)return true;if(!$teacher)return false;
