 foreach($permissions as $key=>$permission){school_require(isset($nd[$key])&&is_array($nd[$key]));$d[$key]=school_merge_rows($d[$key],$visible['d'][$key],$nd[$key],function($old,$row)use($l,$actor,$permission,$key,$state){if(in_array($key,['classes','enrollments'],true)){ $year=school_find($state['d']['years'],$row['yearId']);school_require(!$year||!$year['archived'],'سال بایگانی‌شده قابل تغییر نیست.');}if($key==='students')foreach($state['d']['customFields'] as $f)if($f['required'])school_require(trim($row['extra'][$f['id']]??'')!=='','مشخصه الزامی دانش‌آموز تکمیل نشده است.');school_require(school_can($l,$actor,$permission)||in_array($key,['classes','enrollments'],true)&&school_can($l,$actor,'promotion'));if($key==='enrollments'&&$old)school_only($old,$row,['classId','status']);if($key==='classes'&&$old)school_only($old,$row,['name']);if($key==='years'&&$old)school_require(!$old['archived']||$row['archived'],'بازکردن سال بایگانی‌شده مجاز نیست.');return $row;});}
