 $d['incidents']=school_merge_rows($d['incidents'],$visible['d']['incidents'],$nd['incidents']??[],function($old,$row)use($d,$l,$actor){school_require(school_can($l,$actor,'office')||!$old&&str_starts_with($actor,'teacher:')&&count(array_filter($d['offerings'],fn($o)=>$o['classId']===$row['classId']&&$actor==='teacher:'.$o['teacherId']))>0);if($old)school_only($old,$row,['title','detail','followup','status','date']);else{$row['author']=$actor;if(!school_can($l,$actor,'office')){$row['followup']='';$row['status']='open';}}school_require(in_array($row['status'],['open','in_progress','resolved'],true)&&school_date($row['date']));return $row;});
